      if (field.min !== undefined && n < field.min) return [null, `must be at least ${field.min}`];
      if (field.max !== undefined && n > field.max) return [null, `must be at most ${field.max}`];
      return [field.type === 'money' ? Math.round(n * 100) / 100 : n, null];
